CREATE SCHEMA demo;
CREATE TABLE demo.people (id INTEGER, name TEXT);
CREATE VIEW demo.names AS SELECT name FROM demo.people;
CREATE INDEX people_idx ON demo.people(id);
CREATE TYPE mood AS ENUM ('happy', 'sad');
CREATE FUNCTION greet() RETURNS INTEGER AS $$ SELECT 1; $$ LANGUAGE SQL;
CREATE PROCEDURE reset() LANGUAGE SQL AS $$ SELECT 1; $$;
SELECT greet(), name FROM demo.people;
